INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("1", "Collaboration", "Your success may depend on how effectively you can organize your collaboration with others.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("2", "Communication", "Disorganized and hectic communication will damage your productivity.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("3", "Teamwork", "Organizing work in a group of people is just as essential as selecting the right people to build a team in the first place.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("4", "Delegation", "In fact, your delegation skills are related to your teamwork skills. Well-organized individuals know what they can do themselves, and what they need to delegate to other team members to achieve the best results.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("5", "Planning", "We can easily say that the most important part of a well-organized undertaking happens before anything else even takes place. The ability to plan is arguably the most important attribute of any person who claims to have strong organizational skills.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("6", "Prioritizing", "Being able to give priority to your tasks is far more important than checking off items on your to-do lists. If you can identify roadblocks ahead, break complex projects into smaller components and assess their impact on the outcome, you’re building your project management skills and developing strong problem-solving skills when something doesn't go as planned.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("7", "Mental organizational skills", "This goes far beyond being able to think in a logical and orderly way. Mental organizational skills allow you to research and analyze situations, prepare documentation, or think strategically among others.");
INSERT INTO "organisational_skills" ("skill_id", "name", "description") VALUES ("8", "Physical organization", "Being able to keep your workplace well-organized is also important. If you can’t find necessary documents, office utilities or your computer desktop is so cluttered that you don’t remember what your wallpaper looks like, your workflow will catch a hiccup.");
